/** LaunchConstants.MAX_QUOTE_SUPPLY: the most a quote's own supply may be (B6). */
const BANKR_V4_MAX_QUOTE_SUPPLY = 10n ** 36n;

// Suite 4's hard bounds (design section 2) on a launch's own numbers: one pure function per clause, answering as
// the chain does (null, or the first layer's error). Held to forge's script/vectors/hardBoundVectors.json; the
// setters', a leg's and the factory's are hardBoundsLayers.ts, the curve's (B8 to B10, B17, B12) curveCheck.ts.

/** A bound's refusal: the Solidity error's name and arguments (the settings contract's, the factory's or a leg's). */
export interface BankrV4BoundRefusal {
  error: string;
  args: readonly (bigint | number | Address)[];
}

export type BankrV4BoundVerdict = BankrV4BoundRefusal | null;

export const refuseBankrV4 = (
  error: string,
  ...args: BankrV4BoundRefusal["args"]
): BankrV4BoundRefusal => ({ error, args });

const hard = (bound: number) => refuseBankrV4("HardBound", bound);
const when = (bad: boolean, refusal: BankrV4BoundRefusal) =>
  bad ? refusal : null;

const WAD = 10n ** 18n;
/** B18: a takeover settles every entry of a bucket in one transaction. */
export const BANKR_V4_CTO_MAX_ENTRIES = 64;
/** B1: a buyback fill is sized with 1,000,000 - fee - 100. */
const BUYBACK_MAX_FEE_PIPS = 999_899;
const CLOCK_END = 1n << 40n;

export const bankrV4KnobHardRange = (knob: BankrV4KnobName) => {
  const row = BANKR_V4_KNOBS[BANKR_V4_KNOB[knob]];
  return { min: row.hardMin, max: row.hardMax };
};

/** A value a launch names against its knob's compiled range, the widest any pad's row can be. */
export function bankrV4KnobValueBound(
  knob: BankrV4KnobName,
  value: bigint | number,
): BankrV4BoundVerdict {
  const { min, max } = bankrV4KnobHardRange(knob);
  const v = BigInt(value);
  return when(
    v < min || v > max,
    refuseBankrV4("OutsideLaunchpadRange", BANKR_V4_KNOB[knob], min, max),
  );
}

export interface BankrV4FeeScheduleTerms {
  startPips: number;
  steadyPips: number;
  decaySecs: number;
}

/** B1: each fee under 100 %, steady at most start, and a decay exactly when the two differ. */
export function bankrV4FeeScheduleBound(
  s: BankrV4FeeScheduleTerms,
): BankrV4BoundVerdict {
  return (
    bankrV4KnobValueBound("steadyPips", s.steadyPips) ??
    (s.startPips === s.steadyPips
      ? null
      : bankrV4KnobValueBound("startPips", s.startPips)) ??
    bankrV4KnobValueBound("decaySecs", s.decaySecs) ??
    when(
      s.startPips < s.steadyPips ||
        (s.decaySecs === 0) !== (s.startPips === s.steadyPips),
      refuseBankrV4("InvalidFeeSchedule"),
    )
  );
}

/** B1: from 999,900 pips up a buyback's money could never be spent. `feeCeilingPips` is 0 with no extension. */
export function bankrV4BuybackFeeBound(i: {
  buyback: boolean;
  buySteadyPips: number;
  feeCeilingPips: number;
}): BankrV4BoundVerdict {
  return when(
    i.buyback &&
      (i.buySteadyPips > BUYBACK_MAX_FEE_PIPS ||
        i.feeCeilingPips > BUYBACK_MAX_FEE_PIPS),
    hard(1),
  );
}

/** B2: Bankr's slice beside the referrer's, and its floor inside what the referrer leaves of the lower fee. */
export function bankrV4BankrCutBound(i: {
  bankrFeeBps: number;
  bankrMinPips: number;
  referrerBps: number;
  buySteadyPips: number;
  sellSteadyPips: number;
}): BankrV4BoundVerdict {
  const lower = Math.min(i.buySteadyPips, i.sellSteadyPips);
  return when(
    i.bankrFeeBps + i.referrerBps > 10_000 ||
      i.bankrMinPips * 10_000 > lower * (10_000 - i.referrerBps),
    refuseBankrV4("BankrCutDoesNotFit"),
  );
}

/** B4: holders, auto-LP and buyback are parts of one creator side. */
export function bankrV4SplitsBound(i: {
  holdersBps: number;
  autoLpBps: number;
  buybackBps: number;
}): BankrV4BoundVerdict {
  return when(
    i.holdersBps + i.autoLpBps + i.buybackBps > 10_000,
    refuseBankrV4("InvalidSplits"),
  );
}

export interface BankrV4PadPayeeTerms {
  payees: readonly Address[];
  steadySharesWad: readonly bigint[];
  decay: { on: boolean; autoLpBps: number; sharesWad: readonly bigint[] };
}

const isTreasury = (a: Address) =>
  isAddressEqual(a, BANKR_V4_PAD_TREASURY_MARKER);

/**
 * B4, one share list as the bucket split works it out: its sum, and what is left of the remainder once the treasury
 * marker's cut goes to Bankr's bucket and the others are rescaled over the rest, rounded up. Null: InvalidPayees.
 */
export function bankrV4PadSplit(
  payees: readonly Address[],
  sharesWad: readonly bigint[],
): { sum: bigint; rest: bigint } | null {
  let [sum, cut] = [0n, 0n];
  sharesWad.forEach((share, n) => {
    sum += share;
    if (isTreasury(payees[n]!)) cut = share;
  });
  if (cut >= WAD) return null;
  let rest = WAD;
  for (const [n, share] of sharesWad.entries()) {
    if (isTreasury(payees[n]!)) continue;
    const part = (share * WAD + (WAD - cut) - 1n) / (WAD - cut);
    if (part > rest) return null;
    rest -= part;
  }
  return { sum, rest };
}

/** B5: every clock of a launch fits the 40 bits the hook and the distributor keep. `start` is the trading start. */
export function bankrV4ClocksBound(i: {
  start: bigint;
  vestToHoldersCliff: bigint;
  vestToHoldersDuration: bigint;
  rewardStreamSecs: number;
  capSecs: number;
}): BankrV4BoundVerdict {
  const stream =
    i.start +
    i.vestToHoldersCliff +
    i.vestToHoldersDuration +
    BigInt(i.rewardStreamSecs);
  return when(
    stream >= CLOCK_END || i.start + BigInt(i.capSecs) >= CLOCK_END,
    hard(5),
  );
}

/** B6: a supply in raw units, between one whole token and 1e36. */
export function bankrV4SupplyBound(totalSupply: bigint): BankrV4BoundVerdict {
  const { min, max } = bankrV4KnobHardRange("supply");
  return when(
    totalSupply < min * WAD || totalSupply > max * WAD,
    refuseBankrV4("OutsideLaunchpadRange", BANKR_V4_KNOB.supply, min, max),
  );
}

/** B6: a quote's own raw supply, where it answers totalSupply(), stays inside what the reward accumulator carries. */
export function bankrV4QuoteSupplyBound(
  quoteSupply: bigint | null,
): BankrV4BoundVerdict {
  return when(
    quoteSupply !== null && quoteSupply > BANKR_V4_MAX_QUOTE_SUPPLY,
    hard(6),
  );
}

/** B21 at a price: `amount` raw units of a quote, in whole USD, against the owner's ceiling. */
export function bankrV4QuoteAmountUsdBound(i: {
  amount: bigint;
  decimals: number;
  priceUsdE18: bigint;
  maxCompoundUsd: number;
}): BankrV4BoundVerdict {
  const usd = (i.amount * i.priceUsdE18) / 10n ** BigInt(18 + i.decimals);
  return when(
    usd > BigInt(i.maxCompoundUsd),
    refuseBankrV4("QuoteAmountsOutOfRange"),
  );
}

/** B21's bottom: a compound cap worth under one whole dollar places dust each compound and its backlog never drains. */
export function bankrV4CompoundCapUsdFloorBound(i: {
  compoundCap: bigint;
  decimals: number;
  priceUsdE18: bigint;
}): BankrV4BoundVerdict {
  return when(
    i.compoundCap !== 0n &&
      i.compoundCap * i.priceUsdE18 < 10n ** BigInt(18 + i.decimals),
    refuseBankrV4("QuoteAmountsOutOfRange"),
  );
}

/** B8: an empty pool cannot open. */
export function bankrV4VestedBound(i: {
  supply: bigint;
  vested: bigint;
}): BankrV4BoundVerdict {
  return when(i.vested >= i.supply, refuseBankrV4("VestBpsTooHigh"));
}

/** B11: no size exactly when no length, and a cap of at least one raw unit. */
export function bankrV4CapBound(i: {
  capBps: number;
  capSecs: number;
  totalSupply: bigint;
}): BankrV4BoundVerdict {
  const amount = (i.totalSupply * BigInt(i.capBps)) / 10_000n;
  return when(i.capSecs === 0 ? i.capBps !== 0 : amount === 0n, hard(11));
}

/** B11: the dev buy takes at most the pad's share of supply and, under a cap, the cap amount (0: no cap). */
export function bankrV4DevBuyBound(i: {
  devBuyOut: bigint;
  maxOfSupply: bigint;
  capAmount: bigint;
}): BankrV4BoundVerdict {
  const limit =
    i.capAmount !== 0n && i.capAmount < i.maxOfSupply
      ? i.capAmount
      : i.maxOfSupply;
  return when(i.devBuyOut > limit, refuseBankrV4("DevBuyTooLarge"));
}

/** B12 and B15's `kept`: what a pad's payees (the treasury marker's cut among them) and the referrer leave. */
export function bankrV4KeptWad(i: {
  padPayeesWad: bigint;
  referrerBps: number;
}): bigint {
  const taken = i.padPayeesWad + BigInt(i.referrerBps) * 10n ** 14n;
  return taken < WAD ? WAD - taken : 0n;
}

/** Whether `bps` of what a pad's payees leave of a bucket (`restWad`) is a share at all, as the split rounds it. */
export const bankrV4SharePaid = (restWad: bigint, bps: number): boolean =>
  (restWad * BigInt(bps) + 5_000n) / 10_000n !== 0n;

/** B12: a decay split's auto-LP is paid only while a fee decays; alone, what it leaves under the floor no swap
 *  ever places (only a call of the hook's public compound does). */
export function bankrV4DecayAutoLpBound(i: {
  creatorLp: boolean;
  decayLp: boolean;
  buyDecaySecs: number;
  sellDecaySecs: number;
}): BankrV4BoundVerdict {
  return when(
    i.decayLp &&
      !i.creatorLp &&
      (i.buyDecaySecs !== 0 || i.sellDecaySecs !== 0),
    hard(12),
  );
}

/** B12: a pool that compounds needs a floor, a cap at or over it, and a cap two sides of a band can share. */
export function bankrV4CompoundAmountsBound(i: {
  compoundFloor: bigint;
  compoundCap: bigint;
}): BankrV4BoundVerdict {
  return when(
    i.compoundFloor === 0n ||
      i.compoundFloor > i.compoundCap ||
      i.compoundCap < 2n,
    refuseBankrV4("AutoLpNeedsCompoundTerms"),
  );
}

/** B12: the swap cap a compounding pool stores, half the kept round trip in ticks under the owner's cap. */
export function bankrV4CompoundSwapCap(i: {
  buySteadyPips: number;
  sellSteadyPips: number;
  keptWad: bigint;
  compoundSwapMaxTicks: number;
}): number {
  const cap =
    (BigInt(i.buySteadyPips + i.sellSteadyPips) * i.keptWad) / (200n * WAD);
  return cap > BigInt(i.compoundSwapMaxTicks)
    ? i.compoundSwapMaxTicks
    : Number(cap);
}

/** B12: the gate inside the band's half width and the pool's 16 bits, and a swap cap of at least one tick. */
export function bankrV4CompoundGateBound(i: {
  deviationTicks: number;
  halfWidthSpacings: number;
  swapCapTicks: number;
}): BankrV4BoundVerdict {
  return when(
    i.deviationTicks > i.halfWidthSpacings * BANKR_V4_TICK_SPACING ||
      i.deviationTicks > 0xffff ||
      i.swapCapTicks === 0,
    hard(12),
  );
}

/** B13: an extension's code and budgets as the hook admits them; a budget the launch leaves 0 is its floor. */
export function bankrV4ExtensionBound(i: {
  code: { exists: boolean; startsEf: boolean; atPinnedHash: boolean };
  hasPayee: boolean;
  quoteOnly: boolean;
  quoteGas: number;
  afterGas: number;
}): BankrV4BoundVerdict {
  const admitted = i.code.exists && !i.code.startsEf && i.code.atPinnedHash;
  const after = i.quoteOnly
    ? i.afterGas !== 0
    : i.afterGas < BANKR_V4_EXT_AFTER_GAS ||
      i.afterGas > BANKR_V4_EXT_AFTER_GAS_MAX;
  return when(
    !admitted ||
      !i.hasPayee ||
      i.quoteGas < BANKR_V4_EXT_QUOTE_GAS ||
      i.quoteGas > BANKR_V4_EXT_QUOTE_GAS_MAX ||
      after,
    hard(13),
  );
}

/** B18: the most fee recipients a coin's record says, the pad's row cut to 64 where the coin can be taken over. */
export function bankrV4MaxFeeRecipients(i: {
  feeRecipients: number;
  takeover: boolean;
  knobMax: number;
}): BankrV4BoundRefusal | number {
  if (!i.takeover || i.knobMax <= BANKR_V4_CTO_MAX_ENTRIES) return i.knobMax;
  return i.feeRecipients > BANKR_V4_CTO_MAX_ENTRIES
    ? hard(18)
    : BANKR_V4_CTO_MAX_ENTRIES;
}

export interface BankrV4PresetSite {
  maxPips: number;
  minWindowSecs: number;
  maxWindowSecs: number;
  minBrakeTicks: number;
  minAnchorTau: number;
  maxDustFloor: bigint;
}

/** B14: the dust floor's ceiling a preset is handed, the owner's compound floor for the quote, at least 1,000. */
export function bankrV4PresetDustCeiling(quoteCompoundFloor: bigint): bigint {
  const top = (1n << 112n) - 1n;
  const floor = quoteCompoundFloor < 1_000n ? 1_000n : quoteCompoundFloor;
  return floor > top ? top : floor;
}

/** B14: the one word a preset's constructor is handed (CoinTerms.presetSite); the window's floor is the longer decay. */
export function encodeBankrV4PresetSite(s: BankrV4PresetSite): bigint {
  return (
    BigInt(s.maxPips) |
    (BigInt(s.minWindowSecs) << 24n) |
    (BigInt(s.maxWindowSecs) << 56n) |
    (BigInt.asUintN(24, BigInt(s.minBrakeTicks)) << 88n) |
    (BigInt(s.minAnchorTau) << 112n) |
    (s.maxDustFloor << 144n)
  );
}

export function decodeBankrV4PresetSite(word: bigint): BankrV4PresetSite {
  const at = (shift: number, bits: number) =>
    Number(BigInt.asUintN(bits, word >> BigInt(shift)));
  return {
    maxPips: at(0, 24),
    minWindowSecs: at(24, 32),
    maxWindowSecs: at(56, 32),
    minBrakeTicks: Number(BigInt.asIntN(24, word >> 88n)),
    minAnchorTau: at(112, 32),
    maxDustFloor: word >> 144n,
  };
}

/** B15: a buy, trigger, sell around a buyback fill must lose. */
export function bankrV4BuybackRoundTripBound(i: {
  buySteadyPips: number;
  sellSteadyPips: number;
  keptWad: bigint;
  minRoundTripPips: number;
}): BankrV4BoundVerdict {
  return when(
    BigInt(i.buySteadyPips + i.sellSteadyPips) * i.keptWad <
      BigInt(i.minRoundTripPips) * WAD,
    refuseBankrV4("BuybackFeeTooLow"),
  );
}

/** B16 at the launch: the travel a buyback pool freezes, the compounding figure where it also compounds. */
export function bankrV4FillTravelBound(i: {
  compounds: boolean;
  fillTravelTicks: number;
  fillTravelCompoundingTicks: number;
}): BankrV4BoundVerdict {
  const travel = i.compounds ? i.fillTravelCompoundingTicks : i.fillTravelTicks;
  return when(travel === 0, hard(16));
}

/** B18: what the ledger counts, a bucket's entries, each under 255 and under 64 on a coin that can be taken over. */
export function bankrV4BucketEntriesBound(i: {
  creatorEntries: number;
  decayEntries: number;
  takeover: boolean;
}): BankrV4BoundVerdict {
  const most = i.takeover ? BANKR_V4_CTO_MAX_ENTRIES : 255;
  return when(i.creatorEntries > most || i.decayEntries > most, hard(18));
}

/** B22: a listed quote's coins are never fixed to quote payouts by the order of two owner calls. */
export function bankrV4QuoteRouteBound(i: {
  quote: Address;
  listed: boolean;
  legConverts: boolean;
  legPaysInQuote: boolean;
  quoteIsBnkr: boolean;
  quotePaid: boolean;
}): BankrV4BoundVerdict {
  return when(
    i.listed &&
      !i.legConverts &&
      !i.quotePaid &&
      !i.quoteIsBnkr &&
      !i.legPaysInQuote,
    refuseBankrV4("QuoteHasNoRoute", i.quote),
  );
}
